// v1.4 2026-04-21: 拿掉 require('crypto')（n8n sandbox 擋下），改內嵌 pure-JS SHA-1 + UUID v5
const vars = $('Extract Payload').first().json;
const NAMESPACE = '6ba7b810-9dad-11d1-80b4-00c04fd430c8';

function sha1(bytes) {
  const rotl = (n, x) => ((x << n) | (x >>> (32 - n))) >>> 0;
  const H = [0x67452301, 0xEFCDAB89, 0x98BADCFE, 0x10325476, 0xC3D2E1F0];
  const ml = bytes.length * 8;
  const arr = Array.from(bytes);
  arr.push(0x80);
  while ((arr.length % 64) !== 56) arr.push(0);
  for (let i = 0; i < 4; i++) arr.push(0);
  for (let i = 3; i >= 0; i--) arr.push((ml >>> (i * 8)) & 0xff);
  const words = [];
  for (let i = 0; i < arr.length; i += 4) {
    words.push(((arr[i] << 24) | (arr[i+1] << 16) | (arr[i+2] << 8) | arr[i+3]) >>> 0);
  }
  for (let i = 0; i < words.length; i += 16) {
    const w = words.slice(i, i + 16);
    for (let j = 16; j < 80; j++) w[j] = rotl(1, w[j-3] ^ w[j-8] ^ w[j-14] ^ w[j-16]);
    let a = H[0], b = H[1], c = H[2], d = H[3], e = H[4];
    for (let j = 0; j < 80; j++) {
      let f, k;
      if (j < 20)      { f = (b & c) | ((~b) & d);      k = 0x5A827999; }
      else if (j < 40) { f = b ^ c ^ d;                  k = 0x6ED9EBA1; }
      else if (j < 60) { f = (b & c) | (b & d) | (c & d);k = 0x8F1BBCDC; }
      else             { f = b ^ c ^ d;                  k = 0xCA62C1D6; }
      const t = (rotl(5, a) + f + e + k + w[j]) >>> 0;
      e = d; d = c; c = rotl(30, b); b = a; a = t;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0; H[4] = (H[4] + e) >>> 0;
  }
  const out = new Uint8Array(20);
  for (let i = 0; i < 5; i++) {
    out[i*4]   = (H[i] >>> 24) & 0xff;
    out[i*4+1] = (H[i] >>> 16) & 0xff;
    out[i*4+2] = (H[i] >>> 8)  & 0xff;
    out[i*4+3] =  H[i]         & 0xff;
  }
  return out;
}

function uuidV5(name, namespace) {
  const hex = namespace.replace(/-/g, '');
  const nsBytes = new Uint8Array(16);
  for (let i = 0; i < 16; i++) nsBytes[i] = parseInt(hex.substr(i*2, 2), 16);
  const nameBytes = new TextEncoder().encode(name);
  const msg = new Uint8Array(nsBytes.length + nameBytes.length);
  msg.set(nsBytes, 0);
  msg.set(nameBytes, nsBytes.length);
  const digest = sha1(msg);
  digest[6] = (digest[6] & 0x0f) | 0x50;
  digest[8] = (digest[8] & 0x3f) | 0x80;
  const h = Array.from(digest.slice(0, 16)).map(b => b.toString(16).padStart(2, '0')).join('');
  return `${h.substring(0,8)}-${h.substring(8,12)}-${h.substring(12,16)}-${h.substring(16,20)}-${h.substring(20,32)}`;
}

const out = [];
for (const fileItem of $input.all()) {
  let chunks;
  if (Array.isArray(fileItem.json)) chunks = fileItem.json;
  else if (Array.isArray(fileItem.json.data)) chunks = fileItem.json.data;
  else if (fileItem.json.text) chunks = [fileItem.json];
  else continue;

  const firstMetadata = chunks[0]?.metadata || {};
  const sourceFile = firstMetadata.source_file || fileItem.json.file_name || 'unknown';
  const originalFile = sourceFile.replace(/\.(md|markdown)$/i, '.pdf');

  const createDate = new Date().toISOString().slice(0, 10); // yyyy-MM-dd (UTC)
  chunks.forEach((chunk, idx) => {
    const pointId = uuidV5(`${originalFile}#${idx}`, NAMESPACE);
    const payload = {
      text: chunk.text || '',
      original_file: originalFile,
      source_file: sourceFile,
      file_name: originalFile,      // v1.6 2026-04-21: 前代 相容欄位名
      chunk_index: idx,
      project_name: vars.project_name,
      create_date: createDate,      // v1.6 2026-04-21: 建立日期（對應 前代 $now.format('yyyy-MM-dd')）
      ...(chunk.metadata || {}),
      tags: chunk.tags || [],
      suggested_questions: chunk.suggested_questions || []
    };
    out.push({
      json: {
        point_id: pointId,
        text_to_embed: chunk.text || '',
        qdrant_payload: payload,
        chars: (chunk.text || '').length
      }
    });
  });
}

return out;

// Combine embedding response (either Ollama or OpenAI shape) with prepared points
const embedResponses = $input.all();
const pointItems = $('Loop (batch=4)').all();

return embedResponses.map((r, i) => {
  const src = pointItems[i].json;
  const body = r.json || {};
  let vec = null;
  if (body.embeddings && Array.isArray(body.embeddings)) {
    vec = Array.isArray(body.embeddings[0]) ? body.embeddings[0] : body.embeddings;
  } else if (body.embedding) {
    vec = body.embedding;
  }
  if (!vec && body.data && Array.isArray(body.data) && body.data[0]?.embedding) {
    vec = body.data[0].embedding;
  }
  if (!vec) throw new Error(`Embedding missing for chunk ${src.point_id}: ${JSON.stringify(body).substring(0, 200)}`);
  return {
    json: {
      id: src.point_id,
      vector: vec,
      payload: src.qdrant_payload
    }
  };
});
